3	import type { Path } from 'storybook/internal/types';
4	
5	/**
6	 * Calculate a name to use for a docs entry if not specified. The rule is:
7	 *
8	 * 1. If the name of the MDX file is the "same" as the CSF file (e.g. Button.mdx, Button.stories.jsx)
9	 *    use the default name.
10	 * 2. Else use the (ext-less) name of the MDX file
11	 *
12	 * @param mdxImportPath ImportPath of the MDX file with of={}
13	 * @param csfImportPath ImportPath of the of CSF file
14	 */
15	export function autoName(mdxImportPath: Path, csfImportPath: Path, defaultName: string) {
16	  const mdxBasename = basename(mdxImportPath);
17	  const csfBasename = basename(csfImportPath);
18	
19	  const [mdxFilename] = mdxBasename.split('.');
20	  const [csfFilename] = csfBasename.split('.');
21	
22	  if (mdxFilename === csfFilename) {
23	    return defaultName;
24	  }
25	
26	  return mdxFilename;
27	}
